/** Generated by scaffold-crud-pages. Query hooks for Notifications.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchNotificationsList,
  fetchNotificationsById,
  createNotifications,
  updateNotifications,
  deleteNotifications,
  type FetchNotificationsListParams,
} from '~/services/httpServices/notificationsService';
import type { CreateNotificationsRequest, UpdateNotificationsRequest } from '~/types/notifications';

const DOMAIN = 'notifications';

export function useNotificationsList(params?: FetchNotificationsListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchNotificationsList(params),
  });
}

export function useNotifications(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchNotificationsById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateNotifications() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateNotificationsRequest) => createNotifications(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateNotifications() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateNotificationsRequest }) =>
      updateNotifications(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteNotifications() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteNotifications(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
